    #[test]
    fn random_getrandbits_draws_the_requested_width() {
        exc::init();
        assert_eq!(as_int(call("random", "getrandbits", &[int(0)])), 0);
        for _ in 0..16 {
            let value = as_int(call("random", "getrandbits", &[int(24)]));
            assert!((0..(1 << 24)).contains(&value), "24-bit draw out of range");
        }
        // Wide requests promote instead of raising OverflowError.
        for bits in [60i64, 61, 64, 65, 100, 129, 512] {
            let drawn = call("random", "getrandbits", &[int(bits)]);
            assert!(!exc::pending(), "getrandbits({bits}) raised");
            let n = as_big(drawn);
            assert!(n.sign() != Sign::Minus);
            assert!(
                n.bits() <= bits as u64,
                "draw of {} bits exceeds {bits}",
                n.bits()
            );
            assert_eq!(value::to_string(drawn), n.to_string());
            let dump = call("json", "dumps", &[drawn]);
            assert!(!exc::pending(), "json.dumps raised");
            assert_eq!(
                value::as_str(dump).expect("json str result"),
                n.to_string().as_str()
            );
        }

        // The bit stream is deterministic for a given seed.
        let seed = int(12345);
        let first = call("random", "Random", &[seed]);
        let second = call("random", "Random", &[seed]);
        let draw =
            |rng| crate::methods::call(rng, b"getrandbits".as_ptr(), 11, 1, [int(200)].as_ptr());
        assert_eq!(as_big(draw(first)), as_big(draw(second)));

        exc::init();
        assert_eq!(call("random", "getrandbits", &[int(-1)]), NONE);
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);
        assert_eq!(message(), "number of bits must be non-negative");

        // Memory is capped at the runtime-wide BigInt limit.
        exc::init();
        assert_eq!(
            call("random", "getrandbits", &[int(MAX_GETRANDBITS + 1)]),
            NONE
        );
        assert_eq!(exc::pending_tag(), crate::exc::OVERFLOW_ERROR as i64);

        // The same operation is a `Random` method.
        exc::init();
        let rng = call("random", "Random", &[int(5)]);
        let drawn = crate::methods::call(rng, b"getrandbits".as_ptr(), 11, 1, [int(8)].as_ptr());
        assert!(!exc::pending(), "unexpected exception");
        assert!((0..256).contains(&as_int(drawn)));
    }

    #[test]
    fn os_urandom_returns_requested_entropy_bytes() {
        exc::init();
        assert!(value::as_bytes(call("os", "urandom", &[int(0)]))
            .expect("urandom(0)")
            .is_empty());
        let first = value::as_bytes(call("os", "urandom", &[int(32)]))
            .expect("urandom(32)")
            .to_vec();
        let second = value::as_bytes(call("os", "urandom", &[int(32)]))
            .expect("urandom(32)")
            .to_vec();
        assert!(!exc::pending());
        assert_eq!(first.len(), 32);
        assert_eq!(second.len(), 32);
        assert_ne!(first, second, "two entropy draws must differ");

        exc::init();
        assert_eq!(call("os", "urandom", &[int(-1)]), NONE);
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);
        assert_eq!(message(), "negative argument not allowed");

        exc::init();
        assert_eq!(call("os", "urandom", &[string("4")]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
    }

    #[test]
    fn random_sample_selects_distinct_elements() {
        exc::init();
        let population = value::list_new((0i64..10).map(int).collect());
        for count in [0i64, 1, 5, 10] {
            exc::init();
            let drawn = call("random", "sample", &[population, int(count)]);
            assert!(!exc::pending(), "sample({count}) raised");
            let items = value::as_list(drawn).expect("sample list");
            assert_eq!(items.len(), count as usize);
            let mut numbers: Vec<i64> = items.iter().map(|item| as_int(*item)).collect();
            numbers.sort_unstable();
            numbers.dedup();
            assert_eq!(numbers.len(), count as usize, "sample repeats an element");
            assert!(numbers.iter().all(|n| (0..10).contains(n)));
        }
        // Strings yield a list of one-character strings.
        exc::init();
        let chars = call("random", "sample", &[string("abcdef"), int(3)]);
        assert!(!exc::pending());
        let chars = value::as_list(chars).expect("sample list");
        assert_eq!(chars.len(), 3);
        for item in chars {
            let text = value::as_str(*item).expect("sampled char");
            assert_eq!(text.chars().count(), 1);
            assert!("abcdef".contains(text));
        }
        // Out-of-range counts and non-sequences report the documented errors.
        exc::init();
        assert_eq!(call("random", "sample", &[population, int(-1)]), NONE);
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);
        assert_eq!(message(), "Sample larger than population or is negative");
        exc::init();
        assert_eq!(call("random", "sample", &[population, int(11)]), NONE);
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);
        exc::init();
        assert_eq!(call("random", "sample", &[int(3), int(1)]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
    }

    #[test]
    fn system_random_proxy_exposes_the_secrets_surface() {
        exc::init();
        let proxy = get("random", "SystemRandom");
        assert!(value::as_instance(proxy).is_some());
        assert_eq!(get("random", "SystemRandom"), proxy);
        // Attribute reads yield bound methods, like CPython's class instance.
        let getrandbits = attribute(proxy, "getrandbits");
        assert!(value::as_function(getrandbits).is_some());
        let drawn = call_value(getrandbits, &[int(8)]);
        assert!(!exc::pending());
        assert!(as_int(drawn) < 256);

        // `secrets` also binds `_randbelow`, `choice` and `randbytes`.
        for _ in 0..8 {
            let below = method(proxy, "_randbelow", &[int(4)]);
            assert!(!exc::pending(), "_randbelow raised");
            assert!((0..4).contains(&as_int(below)));
        }
        let picked = method(proxy, "choice", &[value::list_new(vec![int(1), int(2)])]);
        assert!((1..=2).contains(&as_int(picked)));
        let bytes_value = method(proxy, "randbytes", &[int(8)]);
        assert!(!exc::pending(), "randbytes raised");
        assert_eq!(
            value::as_bytes(bytes_value).map(|bytes| bytes.len()),
            Some(8)
        );
        // The module call still produces the proxy (callable class value).
        assert_eq!(call("random", "SystemRandom", &[]), proxy);
    }

    #[test]
    fn random_system_random_draws_from_operating_system_entropy() {
        exc::init();
        let draw = |rng: i64, name: &str, args: &[i64]| {
            crate::methods::call(rng, name.as_ptr(), name.len(), args.len(), args.as_ptr())
        };
        // `SystemRandom` is a module member; its seed is optional and ignored.
        assert!(!exc::pending());
        let rng = call("random", "SystemRandom", &[]);
        assert!(!exc::pending(), "SystemRandom() raised");
        assert_eq!(draw(rng, "seed", &[int(7)]), NONE);
        assert!(!exc::pending(), "SystemRandom.seed(7) raised");
        // Even a seed type the ordinary generator rejects is ignored.
        let text_seed = string("not a seed");
        assert_eq!(draw(rng, "seed", &[text_seed]), NONE);
        assert!(!exc::pending(), "SystemRandom.seed(str) raised");

        let mut floats = Vec::new();
        for _ in 0..16 {
            let drawn = value::as_float(draw(rng, "random", &[])).expect("random() float");
            assert!((0.0..1.0).contains(&drawn), "random() out of range");
            floats.push(drawn);
        }
        floats.dedup();
        assert!(floats.len() > 1, "OS entropy must not repeat one draw");
        for _ in 0..16 {
            let drawn = as_int(draw(rng, "randint", &[int(5), int(7)]));
            assert!((5..=7).contains(&drawn), "randint out of range");
        }
        for _ in 0..16 {
            let drawn = as_int(draw(rng, "randrange", &[int(3), int(9), int(2)]));
            assert!((3..9).contains(&drawn) && drawn % 2 == 1);
        }
        let drawn = value::as_float(draw(rng, "uniform", &[int(2), int(4)])).expect("uniform");
        assert!((2.0..=4.0).contains(&drawn));
        for bits in [1i64, 8, 64, 100] {
            let drawn = draw(rng, "getrandbits", &[int(bits)]);
            assert!(!exc::pending(), "getrandbits({bits}) raised");
            assert!(as_big(drawn).bits() <= bits as u64);
        }
        let sequence = value::list_new(vec![int(1), int(2), int(3)]);
        let picked = as_int(draw(rng, "choice", &[sequence]));
        assert!((1..=3).contains(&picked));
        let sampled = draw(rng, "sample", &[sequence, int(2)]);
        assert!(!exc::pending());
        let sampled = value::as_list(sampled).expect("sample list");
        assert_eq!(sampled.len(), 2);
        assert_ne!(as_int(sampled[0]), as_int(sampled[1]));

        // shuffle permutes the caller's list in place, keeping its elements.
        let shuffled = value::list_new((0i64..8).map(int).collect());
        assert_eq!(draw(rng, "shuffle", &[shuffled]), NONE);
        assert!(!exc::pending());
        let mut items: Vec<i64> = value::as_list(shuffled)
            .expect("shuffled list")
            .iter()
            .map(|item| as_int(*item))
            .collect();
        items.sort_unstable();
        assert_eq!(items, (0i64..8).collect::<Vec<i64>>());

        // An omitted seed slot (keyword binder fills `None`) also works.
        exc::init();
        let seeded = call("random", "SystemRandom", &[NONE]);
        assert!(!exc::pending());
        assert!(value::as_float(draw(seeded, "random", &[])).is_some());
        exc::init();
        assert!(call("random", "SystemRandom", &[string("seed")]) != NONE);
        assert!(!exc::pending());
    }

    #[test]
    fn os_environ_lists_the_process_environment() {
        exc::init();
        std::env::set_var("HYDRO_TEST_OS_ENVIRON", "value");
        let environ = get("os", "environ");
        std::env::remove_var("HYDRO_TEST_OS_ENVIRON");
        let entries = value::as_dict(environ).expect("environ dict");
        let mut found = None;
        for (key, item) in entries {
            if value::as_str(*key) == Some("HYDRO_TEST_OS_ENVIRON") {
                found = Some(*item);
                break;
            }
        }
        let stored = found.expect("os.environ must contain HYDRO_TEST_OS_ENVIRON");
        assert_eq!(value::as_str(stored), Some("value"));
        assert!(!exc::pending());
    }

    #[test]
    fn os_putenv_and_unsetenv_update_the_process_environment() {
        exc::init();
        let name = format!("HYDRO_TEST_PUTENV_{}", std::process::id());
        std::env::remove_var(&name);

        assert_eq!(
            call("os", "putenv", &[string(&name), string("value")]),
            NONE
        );
        assert!(!exc::pending());
        assert_eq!(std::env::var(&name).ok().as_deref(), Some("value"));

        // `os.environ` reads the live process environment, so a new read sees
        // the update (CPython's mapping reflects putenv through the C env).
        let environ = get("os", "environ");
        assert_eq!(
            registry_value(environ, &name).map(value::as_str),
            Some(Some("value"))
        );

        // bytes operands are stored as raw bytes on Unix.
        let bytes_name = value::bytes_new(name.as_bytes().to_vec());
        let bytes_value = value::bytes_new(b"bytes-value".to_vec());
        assert_eq!(call("os", "putenv", &[bytes_name, bytes_value]), NONE);
        assert!(!exc::pending());
        assert_eq!(std::env::var(&name).ok().as_deref(), Some("bytes-value"));

        assert_eq!(call("os", "unsetenv", &[string(&name)]), NONE);
        assert!(!exc::pending());
        assert!(std::env::var_os(&name).is_none());

        // Removing an absent name is not an error.
        assert_eq!(call("os", "unsetenv", &[bytes_name]), NONE);
        assert!(!exc::pending());

        exc::init();
        assert_eq!(call("os", "putenv", &[string("A=B"), string("v")]), NONE);
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);
        assert_eq!(message(), "illegal environment variable name");

        exc::init();
        assert_eq!(
            call(
                "os",
                "putenv",
                &[string("HYDRO_TEST_NUL"), value::bytes_new(b"v\0x".to_vec())]
            ),
            NONE
        );
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);
        assert_eq!(message(), "embedded null byte");

        exc::init();
        assert_eq!(call("os", "putenv", &[string(""), string("v")]), NONE);
        assert_eq!(exc::pending_tag(), OS_ERROR as i64);

        exc::init();
        assert_eq!(call("os", "unsetenv", &[string("A=B")]), NONE);
        assert_eq!(exc::pending_tag(), OS_ERROR as i64);

        // bytearray is bytes-like but not accepted by the converters.
        exc::init();
        assert_eq!(
            call(
                "os",
                "putenv",
                &[
                    value::bytearray_new(b"HYDRO_TEST_BYTEARRAY".to_vec()),
                    string("v")
                ]
            ),
            NONE
        );
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);

        exc::init();
        assert_eq!(call("os", "putenv", &[int(1), string("v")]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        assert_eq!(
            message(),
            "putenv() argument 1 must be str or bytes, not int"
        );
    }

    #[test]
    fn os_listdir_returns_real_directory_entries() {
        exc::init();
        let root = temp_root("os-listdir");
        make_dir(&root.join("sub"));
        std::fs::write(root.join("alpha.txt"), b"x").expect("write file");
        let path = root.to_string_lossy().into_owned();

        let list = call("os", "listdir", &[string(&path)]);
        assert!(!exc::pending());
        let names: Vec<String> = value::as_list(list)
            .expect("listdir result")
            .iter()
            .filter_map(|entry| value::as_str(*entry).map(str::to_string))
            .collect();
        assert!(
            names.iter().any(|name| name.as_str() == "alpha.txt"),
            "{names:?}"
        );
        assert!(names.iter().any(|name| name.as_str() == "sub"), "{names:?}");
        // Directory streams never contain the special entries.
        assert!(!names
            .iter()
            .any(|name| name.as_str() == "." || name.as_str() == ".."));

        // The default path is the current directory.
        let current = call("os", "listdir", &[]);
        assert!(!exc::pending());
        assert!(value::as_list(current).is_some());
        let explicit_none = call("os", "listdir", &[NONE]);
        assert!(!exc::pending());
        assert!(value::as_list(explicit_none).is_some());

        // `path` may be passed by name, like CPython's wrapper.
        let keyword = call_kw("os", "listdir", &[], &[("path", string(&path))]);
        assert!(!exc::pending());
        let keyword_names = value::as_list(keyword).expect("keyword result");
        assert!(keyword_names
            .iter()
            .any(|entry| value::as_str(*entry) == Some("alpha.txt")));

        // A bytes path yields bytes names, matching CPython.
        let byte_path = value::bytes_new(path.as_bytes().to_vec());
        let byte_list = call("os", "listdir", &[byte_path]);
        assert!(!exc::pending());
        let byte_names = value::as_list(byte_list).expect("bytes result");
        assert!(byte_names
            .iter()
            .all(|entry| value::as_bytes(*entry).is_some()));
        assert!(byte_names
            .iter()
            .any(|entry| value::as_bytes(*entry) == Some(&b"alpha.txt"[..])));

        // A missing directory reports OSError with the directory in the
        // message.
        let missing = root.join("does-not-exist");
        exc::init();
        assert_eq!(
            call("os", "listdir", &[string(&missing.to_string_lossy())]),
            NONE
        );
        assert_eq!(exc::pending_tag(), OS_ERROR as i64);
        let missing_text = missing.to_string_lossy().into_owned();
        assert!(message().contains(missing_text.as_str()), "{}", message());

        exc::init();
        assert_eq!(call("os", "listdir", &[int(0)]), NONE);
        assert_eq!(exc::pending_tag(), crate::exc::NOT_IMPLEMENTED_ERROR as i64);

        std::fs::remove_dir_all(&root).expect("remove scratch directory");
    }

    #[test]
    fn os_scandir_yields_real_dir_entries() {
        exc::init();
        let root = temp_root("os-scandir");
        make_dir(&root.join("sub"));
        std::fs::write(root.join("alpha.txt"), b"alpha").expect("write file");
        let path = root.to_string_lossy().into_owned();

        let iterator = call("os", "scandir", &[string(&path)]);
        assert!(!exc::pending(), "{}", message());
        assert!(value::as_instance(iterator).is_some());
        // The module attribute is a callable value too (the stdlib calls
        // `os.scandir` through its attribute table).
        let scandir = get("os", "scandir");
        assert!(value::as_function(scandir).is_some());
        let by_value = call_value(scandir, &[string(&path)]);
        assert!(!exc::pending(), "{}", message());
        assert!(value::as_instance(by_value).is_some());
        // Context manager: __enter__ is the iterator itself, __exit__ does not
        // suppress an exception.
        assert_eq!(method(iterator, "__enter__", &[]), iterator);
        assert_eq!(method(iterator, "__exit__", &[NONE, NONE, NONE]), FALSE);
        assert_eq!(method(iterator, "close", &[]), NONE);
        assert!(!exc::pending());
        assert_ne!(call("os", "scandir", &[string(".")]), NONE);
        assert!(!exc::pending());

        // Drain through the iterator protocol (`for`/`list` use it).
        exc::init();
        let iterator = call("os", "scandir", &[string(&path)]);
        let mut entries = Vec::new();
        loop {
            let entry = method(iterator, "__next__", &[]);
            if exc::pending() {
                assert_eq!(exc::pending_tag(), crate::exc::STOP_ITERATION as i64);
                let _ = exc::clear();
                break;
            }
            entries.push(entry);
        }
        assert_eq!(entries.len(), 2);
        let by_name = |wanted: &str| {
            entries.iter().copied().find(|entry| {
                value::instance_attr(*entry, "name").and_then(value::as_str) == Some(wanted)
            })
        };
        let alpha = by_name("alpha.txt").expect("file entry");
        let sub = by_name("sub").expect("directory entry");
        let expected_path = root.join("alpha.txt").to_string_lossy().into_owned();
        assert_eq!(
            value::instance_attr(alpha, "path").and_then(value::as_str),
            Some(expected_path.as_str())
        );
        assert_eq!(method(alpha, "is_file", &[]), TRUE);
        assert_eq!(method(alpha, "is_dir", &[]), FALSE);
        assert_eq!(method(alpha, "is_symlink", &[]), FALSE);
        assert_eq!(
            method_kw(alpha, "is_file", &[], &[("follow_symlinks", FALSE)]),
            TRUE
        );
        assert_eq!(method(sub, "is_dir", &[]), TRUE);
        assert_eq!(method(sub, "is_file", &[]), FALSE);
        let metadata = method(alpha, "stat", &[]);
        assert!(!exc::pending(), "{}", message());
        let inode = namespace_value(metadata, "st_ino").expect("st_ino");
        assert_eq!(method(alpha, "inode", &[]), inode);
        assert!(method_kw(alpha, "stat", &[], &[("follow_symlinks", FALSE)]).ne(&NONE));
        let fspath = crate::core::methods::getattr(alpha, b"__fspath__".as_ptr(), 10);
        assert!(!exc::pending(), "{}", message());
        let resolved = call_value(fspath, &[]);
        assert_eq!(
            value::as_str(resolved),
            value::instance_attr(alpha, "path").and_then(value::as_str)
        );

        // A missing directory is an OSError with CPython's wording.
        exc::init();
        let missing = root.join("does-not-exist");
        assert_eq!(
            call("os", "scandir", &[string(&missing.to_string_lossy())]),
            NONE
        );
        assert_eq!(exc::pending_tag(), crate::exc::FILE_NOT_FOUND_ERROR as i64);
        let missing_text = missing.to_string_lossy().into_owned();
        assert!(message().contains(missing_text.as_str()));
    }

    #[test]
    fn os_path_common_helpers_match_posixpath() {
        exc::init();
        let sequence = |items: &[&str]| {
            value::list_new(items.iter().map(|item| string(item)).collect::<Vec<_>>())
        };
        assert_eq!(
            value::as_str(call(
                "os.path",
                "commonprefix",
                &[sequence(&["abc", "abd"])]
            )),
            Some("ab")
        );
        assert_eq!(
            value::as_str(call("os.path", "commonprefix", &[sequence(&[])])),
            Some("")
        );
        let raw = call(
            "os.path",
            "commonprefix",
            &[value::list_new(vec![
                value::bytes_new(b"abc".to_vec()),
                value::bytes_new(b"abd".to_vec()),
            ])],
        );
        assert_eq!(value::as_bytes(raw), Some(&b"ab"[..]));

        assert_eq!(
            value::as_str(call(
                "os.path",
                "commonpath",
                &[sequence(&["/usr/lib", "/usr/local"])]
            )),
            Some("/usr")
        );
        assert_eq!(
            value::as_str(call("os.path", "commonpath", &[sequence(&["/a", "/b"])])),
            Some("/")
        );
        assert_eq!(
            value::as_str(call("os.path", "commonpath", &[sequence(&["a", "b"])])),
            Some("")
        );
        assert_eq!(
            value::as_str(call("os.path", "commonpath", &[sequence(&["a/b", "a/c"])])),
            Some("a")
        );
        exc::init();
        assert_eq!(call("os.path", "commonpath", &[sequence(&[])]), NONE);
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);
        exc::init();
        assert_eq!(
            call("os.path", "commonpath", &[sequence(&["a", "/b"])]),
            NONE
        );
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);

        assert_eq!(
            value::as_str(call("os.path", "relpath", &[string("a/b"), string("a")])),
            Some("b")
        );
        assert_eq!(
            value::as_str(call("os.path", "relpath", &[string("a/b"), string("a/c")])),
            Some("../b")
        );
        assert_eq!(
            value::as_str(call("os.path", "relpath", &[string("a"), string("b")])),
            Some("../a")
        );
        // The alias spelling shares `os.path`'s dispatch.
        assert_eq!(
            value::as_str(call(
                "posixpath",
                "commonpath",
                &[sequence(&["/usr/lib", "/usr/local"])]
            )),
            Some("/usr")
        );

        let root = temp_root("os-path-lexists");
        let existing = root.join("present");
        std::fs::write(&existing, b"x").expect("write file");
        assert_eq!(
            call("os.path", "lexists", &[string(&existing.to_string_lossy())]),
            TRUE
        );
        assert_eq!(
            call_value(
                get("os.path", "lexists"),
                &[string(&existing.to_string_lossy())]
            ),
            TRUE
        );
        assert_eq!(
            call(
                "os.path",
                "lexists",
                &[string(&root.join("absent").to_string_lossy())]
            ),
            FALSE
        );
        // ALLOW_MISSING is one cached sentinel across every path spelling.
        let sentinel = get("os.path", "ALLOW_MISSING");
        assert_eq!(sentinel, get("posixpath", "ALLOW_MISSING"));
        assert_eq!(sentinel, get("ntpath", "ALLOW_MISSING"));
    }

