    #[test]
    fn dataclasses_fields_reads_the_metadata_mapping() {
        exc::init();
        let first = call("dataclasses", "field", &[]);
        let second = call_kw("dataclasses", "field", &[], &[("default", int(7))]);
        let metadata = value::dict_new(Vec::new());
        container::dict_set(metadata, string("alpha"), first);
        container::dict_set(metadata, string("beta"), second);

        let class = value::class_new("Located".to_string(), NONE, Vec::new());
        value::class_set_attr(class, "__dataclass_fields__".to_string(), metadata);
        let instance = value::instance_new(class);

        // Declaration order follows the mapping, on both a class and an
        // instance, and the mapping keys supply the unset `Field.name`s.
        let by_class = call("dataclasses", "fields", &[class]);
        assert!(!exc::pending(), "{}", message());
        let by_instance = call("dataclasses", "fields", &[instance]);
        assert!(!exc::pending(), "{}", message());
        for result in [by_class, by_instance] {
            let items = value::as_tuple(result).expect("tuple of fields");
            assert_eq!(items, &[first, second][..]);
            let name_at =
                |index: usize| value::instance_attr(items[index], "name").and_then(value::as_str);
            assert_eq!(name_at(0), Some("alpha"));
            assert_eq!(name_at(1), Some("beta"));
            assert_eq!(value::instance_attr(items[1], "default"), Some(int(7)));
        }

        // A non-dataclass (and a non-dict metadata attribute) raises CPython's
        // TypeError rather than fabricating fields.
        exc::init();
        assert_eq!(call("dataclasses", "fields", &[int(1)]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        assert_eq!(
            message(),
            "fields() should be called with a dataclass type or instance"
        );
        exc::init();
        let plain = value::class_new("Plain".to_string(), NONE, Vec::new());
        assert_eq!(call("dataclasses", "fields", &[plain]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        exc::init();
        let bogus = value::class_new("Bogus".to_string(), NONE, Vec::new());
        value::class_set_attr(bogus, "__dataclass_fields__".to_string(), int(1));
        assert_eq!(call("dataclasses", "fields", &[bogus]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        assert_eq!(
            message(),
            "fields() should be called with a dataclass type or instance"
        );
    }

    #[test]
    fn dataclasses_replace_copies_the_instance() {
        exc::init();
        let class = value::class_new("Point".to_string(), NONE, Vec::new());
        let instance = value::instance_new(class);
        value::instance_setattr(instance, "x".to_string(), int(1));
        value::instance_setattr(instance, "y".to_string(), int(2));

        // `replace(self, y=9, z=3)`: `y` overwrites the copied slot, `z` is
        // added after the existing attributes.
        let y_name = string("y");
        let z_name = string("z");
        let keywords = [y_name, int(9), z_name, int(3)];
        let copy = module_call_kw(
            b"dataclasses".as_ptr(),
            11,
            b"replace".as_ptr(),
            7,
            1,
            &instance,
            2,
            keywords.as_ptr(),
        );
        assert!(
            !exc::pending(),
            "{}",
            value::to_string(exc::pending_value())
        );
        let state = value::as_instance(copy).expect("instance copy");
        assert_eq!(state.class, class);
        let pairs: Vec<(String, i64)> = state.lock_attrs().clone();
        assert_eq!(
            pairs
                .iter()
                .map(|(name, _)| name.as_str())
                .collect::<Vec<_>>(),
            ["x", "y", "z"],
            "insertion order is preserved and the new name is appended"
        );
        assert_eq!(pairs[0].1, int(1));
        assert_eq!(pairs[1].1, int(9));
        assert_eq!(pairs[2].1, int(3));

        // The original instance is untouched.
        assert_eq!(value::instance_attr(instance, "y"), Some(int(2)));
        assert_eq!(value::instance_attr(instance, "z"), None);
        assert_eq!(value::instance_attr(instance, "x"), Some(int(1)));

        // The positional form copies without changes.
        let plain = call("dataclasses", "replace", &[instance]);
        assert!(!exc::pending());
        assert_ne!(plain, instance);
        assert_eq!(value::instance_attr(plain, "x"), Some(int(1)));
        assert_eq!(value::instance_attr(plain, "y"), Some(int(2)));

        // `get` exposes the same callable value.
        assert!(value::as_function(get("dataclasses", "replace")).is_some());

        // A non-instance is rejected.
        exc::init();
        assert_eq!(call("dataclasses", "replace", &[int(1)]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        assert_eq!(
            value::to_string(exc::pending_value()),
            "replace() should be called on dataclass instances"
        );
        exc::init();
    }

    #[test]
    fn dataclasses_asdict_converts_nested_values() {
        exc::init();
        // Nested dataclass `Inner(value)`.
        let inner_field = call("dataclasses", "field", &[]);
        let inner_metadata = value::dict_new(vec![(string("value"), inner_field)]);
        let inner_class = value::class_new("Inner".to_string(), NONE, Vec::new());
        value::class_set_attr(
            inner_class,
            "__dataclass_fields__".to_string(),
            inner_metadata,
        );
        let inner = value::instance_new(inner_class);
        let inner_roots = heap::root_values(&[inner]);
        value::instance_setattr(inner, "value".to_string(), int(7));

        // `Outer` holds a scalar, a list, a nested dataclass, a tuple and a
        // dict, so every recursion branch is exercised.
        let fields: Vec<(i64, i64)> = ["x", "y", "z", "t", "m"]
            .into_iter()
            .map(|name| (string(name), call("dataclasses", "field", &[])))
            .collect();
        let metadata = value::dict_new(fields);
        let class = value::class_new("Outer".to_string(), NONE, Vec::new());
        value::class_set_attr(class, "__dataclass_fields__".to_string(), metadata);
        let instance = value::instance_new(class);
        value::instance_setattr(instance, "x".to_string(), int(1));
        value::instance_setattr(
            instance,
            "y".to_string(),
            value::list_new(vec![int(2), int(3)]),
        );
        value::instance_setattr(instance, "z".to_string(), inner);
        value::instance_setattr(
            instance,
            "t".to_string(),
            value::tuple_new(vec![int(4), int(5)]),
        );
        let mapped_value = value::list_new(vec![int(6)]);
        let mapped_roots = heap::root_values(&[mapped_value]);
        let mapping = value::dict_new(vec![(string("k"), mapped_value)]);
        heap::release_roots(mapped_roots);
        value::instance_setattr(instance, "m".to_string(), mapping);
        let roots = heap::root_values(&[instance]);

        let result = call("dataclasses", "asdict", &[instance]);
        assert!(!exc::pending(), "{}", message());
        let pairs = value::as_dict(result).expect("asdict returns a dict");
        assert_eq!(pairs.len(), 5);
        let entry = |name: &str| {
            pairs
                .iter()
                .find(|(key, _)| value::as_str(*key) == Some(name))
                .map(|(_, value)| *value)
        };
        assert_eq!(entry("x"), Some(int(1)));
        assert_eq!(
            value::as_list(entry("y").expect("y")).map(|items| items.to_vec()),
            Some(vec![int(2), int(3)]),
            "lists keep their element order"
        );
        let nested = value::as_dict(entry("z").expect("z")).expect("nested dataclass dict");
        assert_eq!(value::as_str(nested[0].0), Some("value"));
        assert_eq!(
            nested[0].1,
            int(7),
            "nested dataclasses convert recursively"
        );
        assert_eq!(
            value::as_tuple(entry("t").expect("t")).map(|items| items.to_vec()),
            Some(vec![int(4), int(5)]),
            "tuples stay tuples"
        );
        let mapped = value::as_dict(entry("m").expect("m")).expect("dict stays a dict");
        assert_eq!(value::as_str(mapped[0].0), Some("k"));
        assert_eq!(
            value::as_list(mapped[0].1).map(|items| items.to_vec()),
            Some(vec![int(6)]),
            "dict values convert recursively"
        );

        // `dict_factory` receives the list of `(name, value)` tuples, like
        // CPython; an identity factory exposes it directly.
        let identity = value::identity_function_new("factory");
        let identity_roots = heap::root_values(&[identity]);
        let factory_result = call_kw(
            "dataclasses",
            "asdict",
            &[instance],
            &[("dict_factory", identity)],
        );
        assert!(!exc::pending(), "{}", message());
        let listed = value::as_list(factory_result).expect("factory receives a list");
        assert_eq!(listed.len(), 5);
        let head = value::as_tuple(listed[0]).expect("each entry is a tuple");
        assert_eq!(value::as_str(head[0]), Some("x"));
        assert_eq!(head[1], int(1));

        // The `obj` keyword form is accepted.
        let by_keyword = call_kw("dataclasses", "asdict", &[], &[("obj", instance)]);
        assert!(!exc::pending(), "{}", message());
        assert_eq!(
            value::as_dict(by_keyword).map(|entries| entries.len()),
            Some(5)
        );

        // Classes are not instances, and a missing argument is rejected.
        exc::init();
        assert_eq!(call("dataclasses", "asdict", &[class]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        assert_eq!(
            message(),
            "asdict() should be called on dataclass instances"
        );
        exc::init();
        assert_eq!(call("dataclasses", "asdict", &[]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);

        heap::release_roots(identity_roots);
        heap::release_roots(roots);
        heap::release_roots(inner_roots);
    }

