    #[test]
    fn incremental_newline_decoder_translates_like_cpython() {
        let _heap_guard = crate::heap::heap_reset_test_guard();
        exc::init();
        // The class is a real module attribute, shared by `io` and `_io`.
        let class = get("io", "IncrementalNewlineDecoder");
        assert!(value::as_class(class).is_some());
        assert_eq!(class, get("_io", "IncrementalNewlineDecoder"));
        let method = |name: &str| match value::class_lookup(class, name) {
            Some(value::ClassEntry::Method(_, function))
            | Some(value::ClassEntry::Attr(function)) => function,
            None => panic!("missing {name} method"),
        };
        let decode = method("decode");
        let getstate = method("getstate");
        let setstate = method("setstate");
        let reset = method("reset");
        let decode = |decoder: i64, text: i64, final_input: i64| {
            call_value(decode, &[decoder, text, final_input])
        };

        // `doctest`'s exact use: decoder=None, translate=True, final=True.
        let decoder = call("io", "IncrementalNewlineDecoder", &[NONE, TRUE]);
        assert!(value::as_instance(decoder).is_some());
        assert_eq!(
            value::as_str(decode(decoder, string("a\r\nb\rc\n"), TRUE)),
            Some("a\nb\nc\n")
        );
        let observed: Vec<String> =
            value::as_tuple(value::instance_attr(decoder, "newlines").expect("newlines attribute"))
                .expect("newlines tuple")
                .iter()
                .map(|name| value::as_str(*name).expect("newline name").to_string())
                .collect();
        assert_eq!(
            observed,
            vec!["\r".to_string(), "\n".to_string(), "\r\n".to_string()]
        );

        // A trailing `\r` is held until the next chunk (or the final call), so
        // a split `\r\n` becomes one newline rather than two.
        let split = call("io", "IncrementalNewlineDecoder", &[NONE, TRUE]);
        assert_eq!(
            value::as_str(decode(split, string("a\r"), FALSE)),
            Some("a")
        );
        assert_eq!(
            value::as_str(decode(split, string("\nb"), TRUE)),
            Some("\nb")
        );

        // `translate=False` preserves the line endings but still joins a
        // split `\r\n` into a single `\r\n` (it is one newline, not two).
        let raw = call("io", "IncrementalNewlineDecoder", &[NONE, FALSE]);
        assert_eq!(value::as_str(decode(raw, string("a\r"), FALSE)), Some("a"));
        assert_eq!(
            value::as_str(decode(raw, string("\nb\r\nc"), TRUE)),
            Some("\r\nb\r\nc")
        );

        // State round-trips through `getstate`/`setstate`; `reset` clears the
        // pending text and the observed newline kinds.
        let state = call_value(getstate, &[split]);
        assert!(value::as_tuple(state).is_some());
        assert_eq!(call_value(setstate, &[split, state]), NONE);
        assert!(!exc::pending(), "{}", message());
        assert_eq!(call_value(reset, &[split]), NONE);
        assert_eq!(value::instance_attr(split, "newlines"), Some(NONE));
        assert!(!exc::pending(), "{}", message());
    }

    #[test]
    fn new_stdlib_surfaces_resolve_through_the_module_api() {
        // Nothing may reset the heap while this test resolves classes and
        // instances: the values it compares are owned by that heap.
        let _heap_guard = crate::heap::heap_reset_test_guard();
        exc::init();
        // Module-level caches are process-global: the `globals` registry holds
        // the cached classes/instances and each module's native class
        // registry compares against the heap generation. Every test that
        // resets that state (or calls `hydro_runtime_init`) holds the same
        // runtime-state lock, so no reset can interleave here; keep the
        // assertions broad anyway because this smoke test resolves many
        // independent caches.
        //
        // `functools.Placeholder` is a public value (the singleton instance of
        // its type); the repeat read shows the cache returns one value.
        let placeholder = get("functools", "Placeholder");
        assert_eq!(placeholder, get("functools", "Placeholder"));
        assert!(
            value::as_instance(placeholder).is_some(),
            "functools.Placeholder is not an instance"
        );

        // `functools.partialmethod` is a class value and a constructor.
        let pm_class = get("functools", "partialmethod");
        assert!(value::as_class(pm_class).is_some());
        let pm = call(
            "functools",
            "partialmethod",
            &[get("functools", "reduce"), int(0)],
        );
        assert!(
            value::as_instance(pm).is_some(),
            "functools.partialmethod(...) returned no instance"
        );

        // `ast.arg` may be built against a class registry rebuilt by another
        // test's reset, so only the shape of the result is checked here;
        // `ast`'s own tests assert the exact `arg` class of the node.
        let arg = call("ast", "arg", &[string("x")]);
        assert!(
            value::as_instance(arg).is_some(),
            "ast.arg(...) returned no instance"
        );

        // `types.DynamicClassAttribute` is a class value and a constructor.
        let dca_class = get("types", "DynamicClassAttribute");
        assert!(value::as_class(dca_class).is_some());
        let dca = call("types", "DynamicClassAttribute", &[]);
        assert!(
            value::as_instance(dca).is_some(),
            "types.DynamicClassAttribute(...) returned no instance"
        );

        // `sys` recursion limit is a real process-wide setting.
        let limit = as_int(call("sys", "getrecursionlimit", &[]));
        assert!(limit > 0);
        assert_eq!(call("sys", "setrecursionlimit", &[int(limit)]), NONE);
        assert_eq!(as_int(call("sys", "getrecursionlimit", &[])), limit);
        assert_eq!(call("sys", "setrecursionlimit", &[int(0)]), NONE);
        assert_eq!(exc::pending_tag(), RECURSION_ERROR as i64);
        exc::init();

        // `os.path.normcase` is the POSIX identity.
        assert_eq!(
            text_at(
                "os.path.normcase",
                call("os.path", "normcase", &[string("/tmp/Mixed/Case")]),
            ),
            "/tmp/Mixed/Case"
        );

        // `os.path.realpath` resolves a symlinked directory.
        let root = temp_root("realpath");
        let dir = make_dir(&root.join("dir"));
        std::fs::write(dir.join("file.txt"), b"x").expect("write file");
        let link = root.join("link");
        #[cfg(unix)]
        std::os::unix::fs::symlink(&dir, &link).expect("create symlink");
        let resolved = text_at(
            "os.path.realpath",
            call(
                "os.path",
                "realpath",
                &[value::str_alloc(link.to_string_lossy().into_owned())],
            ),
        );
        assert!(resolved.ends_with("/dir"), "{resolved}");
        assert!(!resolved.contains("/link"), "{resolved}");

        // Non-strict keeps a missing path absolute; strict raises OSError.
        let missing = root.join("absent");
        let lenient = text_at(
            "os.path.realpath",
            call(
                "os.path",
                "realpath",
                &[value::str_alloc(missing.to_string_lossy().into_owned())],
            ),
        );
        assert!(Path::new(&lenient).is_absolute());
        exc::init();
        call(
            "os.path",
            "realpath",
            &[
                value::str_alloc(missing.to_string_lossy().into_owned()),
                TRUE,
            ],
        );
        assert_eq!(exc::pending_tag(), OS_ERROR as i64);
        exc::init();
        std::fs::remove_dir_all(&root).ok();
    }

