    #[test]
    fn text_io_wrapper_reads_and_writes_file_objects() {
        exc::init();
        let dir = temp_root("textio");
        let path = dir.join("data.txt");
        std::fs::write(&path, b"hello\nworld\n").unwrap();
        let path_text = path.to_string_lossy().into_owned();

        let file = call("io", "open", &[string(&path_text), string("rb")]);
        assert!(!exc::pending());
        let wrapper = call("io", "TextIOWrapper", &[file]);
        assert!(!exc::pending());
        // The wrapper is an instance of the native `io.TextIOWrapper` class:
        // `type(wrapper)` is that class and its `__name__` is what the runtime
        // reports on the resolving paths. `value::type_name` is the static
        // fallback (it answers "instance" for every class instance by design).
        let wrapper_class = value::type_class(wrapper);
        assert_eq!(
            value::class_display_name(wrapper_class),
            Some("TextIOWrapper")
        );
        assert_eq!(
            wrapper_class,
            get("io", "TextIOWrapper"),
            "type(wrapper) must be the module's TextIOWrapper class"
        );
        assert_eq!(attribute(wrapper, "__class__"), wrapper_class);
        assert_eq!(
            value::as_str(attribute(wrapper_class, "__name__")),
            Some("TextIOWrapper")
        );
        assert_eq!(value::type_name_of(wrapper), "TextIOWrapper");
        assert_eq!(value::as_str(attribute(wrapper, "encoding")), Some("utf-8"));
        assert_eq!(
            value::as_str(attribute(wrapper, "name")),
            Some(path_text.as_str())
        );
        assert_eq!(value::as_str(attribute(wrapper, "mode")), Some("rb"));
        assert_eq!(value::as_str(attribute(wrapper, "errors")), Some("strict"));
        assert_eq!(attribute(wrapper, "closed"), FALSE);
        assert_eq!(attribute(wrapper, "line_buffering"), FALSE);
        assert_eq!(attribute(wrapper, "write_through"), FALSE);

        let line = method(wrapper, "readline", &[]);
        assert_eq!(value::as_str(line), Some("hello\n"));
        assert_eq!(value::as_str(attribute(wrapper, "newlines")), Some("\n"));
        let rest = method(wrapper, "read", &[]);
        assert_eq!(value::as_str(rest), Some("world\n"));
        let eof = method(wrapper, "readline", &[]);
        assert_eq!(value::as_str(eof), Some(""));
        method(wrapper, "close", &[]);
        assert_eq!(attribute(wrapper, "closed"), TRUE);

        // Writes go to the wrapped binary file, with the text layer encoding.
        let out = dir.join("out.txt");
        let out_text = out.to_string_lossy().into_owned();
        let file = call("io", "open", &[string(&out_text), string("wb")]);
        assert!(!exc::pending());
        let wrapper = call("io", "TextIOWrapper", &[file]);
        assert!(!exc::pending());
        let written = method(wrapper, "write", &[string("a\nb")]);
        assert_eq!(as_int(written), 3);
        method(wrapper, "flush", &[]);
        method(wrapper, "close", &[]);
        assert_eq!(std::fs::read_to_string(&out).unwrap(), "a\nb");
    }

    #[test]
    fn contextlib_nullcontext_enters_with_its_result_and_does_not_suppress() {
        exc::init();
        let manager = call("contextlib", "nullcontext", &[string("resource")]);
        assert!(!exc::pending());
        assert_eq!(
            value::class_display_name(value::instance_class_value(manager).expect("instance")),
            Some("nullcontext")
        );
        assert_eq!(
            value::as_str(attribute(manager, "enter_result")),
            Some("resource")
        );
        assert_eq!(
            value::as_str(method(manager, "__enter__", &[])),
            Some("resource")
        );
        // CPython's nullcontext is reusable: `__enter__` re-reads the stored
        // result instead of consuming it.
        assert_eq!(
            value::as_str(method(manager, "__enter__", &[])),
            Some("resource")
        );
        // `False` keeps the exception raised by the block.
        assert_eq!(method(manager, "__exit__", &[NONE, NONE, NONE]), FALSE);

        // The default `enter_result` is `None`.
        let bare = call("contextlib", "nullcontext", &[]);
        assert!(!exc::pending());
        assert_eq!(attribute(bare, "enter_result"), NONE);
        assert_eq!(method(bare, "__enter__", &[]), NONE);
        assert_eq!(method(bare, "__exit__", &[NONE, NONE, NONE]), FALSE);

        // `suppress` shares the same native-method dispatch, so its internal
        // methods must be registered in the module table as well.
        let suppress = call("contextlib", "suppress", &[]);
        assert!(!exc::pending());
        assert_eq!(method(suppress, "__enter__", &[]), NONE);
        // `None` is falsy: the manager never suppresses the block exception.
        assert_eq!(method(suppress, "__exit__", &[NONE, NONE, NONE]), NONE);
    }

    // Generator bodies for the `contextmanager` tests. A generator function
    // value is created with `FUNCTION_FLAG_GENERATOR`, so calling it produces
    // a fiber whose body runs these entry points on the fiber stack.
    extern "C" fn cm_yield_once(_argv: *const i64) -> i64 {
        crate::fiber::yield_value(int(1));
        NONE
    }

    extern "C" fn cm_yield_twice(_argv: *const i64) -> i64 {
        crate::fiber::yield_value(int(1));
        crate::fiber::yield_value(int(2));
        NONE
    }

    extern "C" fn cm_yield_nothing(_argv: *const i64) -> i64 {
        NONE
    }

    extern "C" fn cm_echo(argv: *const i64) -> i64 {
        // SAFETY: the decorator test calls the generator function with exactly
        // one positional (or bound keyword) argument.
        let value = unsafe { *argv };
        crate::fiber::yield_value(value);
        NONE
    }

    extern "C" fn cm_swallow_yield(_argv: *const i64) -> i64 {
        crate::fiber::yield_value(int(1));
        // `except Exception: pass`: the thrown exception surfaces as the
        // pending exception at the suspension point.
        if exc::pending() {
            let _ = exc::clear();
        }
        NONE
    }

    extern "C" fn cm_propagate_yield(_argv: *const i64) -> i64 {
        crate::fiber::yield_value(int(1));
        // Leave the injected exception pending: it escapes the generator.
        NONE
    }

    extern "C" fn cm_swallow_then_yield(_argv: *const i64) -> i64 {
        crate::fiber::yield_value(int(1));
        if exc::pending() {
            let _ = exc::clear();
        }
        crate::fiber::yield_value(int(2));
        NONE
    }

    extern "C" fn cm_swallow_then_raise(_argv: *const i64) -> i64 {
        crate::fiber::yield_value(int(1));
        if exc::pending() {
            let _ = exc::clear();
        }
        exc::raise_with_message(VALUE_ERROR, "from generator");
        NONE
    }

    extern "C" fn cm_not_a_generator(_argv: *const i64) -> i64 {
        int(7)
    }

    /// A generator function value produced by the given fiber entry point.
    fn generator_function(
        entry: extern "C" fn(*const i64) -> i64,
        arity: usize,
        name: &str,
    ) -> i64 {
        value::function_new_with_flags(
            entry as usize,
            arity,
            name.to_string(),
            value::FUNCTION_FLAG_GENERATOR,
        )
    }

    /// Applies `contextlib.contextmanager` to `function` and calls the
    /// resulting decorator value with `args`.
    fn contextmanager_manager(function: i64, args: &[i64]) -> i64 {
        let decorator = call("contextlib", "contextmanager", &[function]);
        assert!(!exc::pending());
        let manager = call_value(decorator, args);
        assert!(!exc::pending());
        manager
    }

    /// A detached exception value, leaving no pending exception behind.
    fn exception(tag: u32, text: &str) -> i64 {
        exc::raise_with_message(tag, text);
        let value = exc::pending_value();
        let _ = exc::clear();
        value
    }

    #[test]
    fn contextlib_contextmanager_enter_advances_and_exit_finishes() {
        exc::init();
        let manager = contextmanager_manager(generator_function(cm_yield_once, 0, "once"), &[]);
        assert_eq!(
            value::class_display_name(
                value::instance_class_value(manager).expect("context manager instance")
            ),
            Some("_GeneratorContextManager")
        );
        assert_eq!(as_int(method(manager, "__enter__", &[])), 1);
        assert!(!exc::pending());
        // The normal exit resumes the generator; it returns, so nothing is
        // suppressed.
        assert_eq!(method(manager, "__exit__", &[NONE, NONE, NONE]), FALSE);
        assert!(!exc::pending());

        // Each decorated call owns a fresh generator: the same decorator can
        // be used again.
        let second = contextmanager_manager(generator_function(cm_yield_once, 0, "once"), &[]);
        assert_eq!(as_int(method(second, "__enter__", &[])), 1);
        assert_eq!(method(second, "__exit__", &[NONE, NONE, NONE]), FALSE);
    }

    #[test]
    fn contextlib_contextmanager_reports_didnt_yield_and_didnt_stop() {
        exc::init();
        let empty = contextmanager_manager(generator_function(cm_yield_nothing, 0, "nothing"), &[]);
        assert_eq!(method(empty, "__enter__", &[]), NONE);
        assert_eq!(exc::pending_tag(), crate::exc::RUNTIME_ERROR as i64);
        assert_eq!(message(), "generator didn't yield");

        exc::init();
        let twice = contextmanager_manager(generator_function(cm_yield_twice, 0, "twice"), &[]);
        assert_eq!(as_int(method(twice, "__enter__", &[])), 1);
        assert_eq!(method(twice, "__exit__", &[NONE, NONE, NONE]), NONE);
        assert_eq!(exc::pending_tag(), crate::exc::RUNTIME_ERROR as i64);
        assert_eq!(message(), "generator didn't stop");
        // The error path closed the suspended generator.
        assert!(crate::fiber::is_done(
            value::instance_attr(twice, "gen").expect("generator")
        ));
    }

    #[test]
    fn contextlib_contextmanager_exit_throws_the_block_exception() {
        exc::init();
        let swallowing =
            contextmanager_manager(generator_function(cm_swallow_yield, 0, "swallow"), &[]);
        assert_eq!(as_int(method(swallowing, "__enter__", &[])), 1);
        let boom = exception(VALUE_ERROR, "boom");
        // The generator handled the exception and returned: suppress it.
        assert_eq!(method(swallowing, "__exit__", &[NONE, boom, NONE]), TRUE);
        assert!(!exc::pending());

        exc::init();
        let propagating =
            contextmanager_manager(generator_function(cm_propagate_yield, 0, "propagate"), &[]);
        assert_eq!(as_int(method(propagating, "__enter__", &[])), 1);
        let boom = exception(VALUE_ERROR, "boom");
        // The same exception escapes the generator: do not suppress it. The
        // `with` lowering re-raises the exception it is still holding.
        assert_eq!(method(propagating, "__exit__", &[NONE, boom, NONE]), FALSE);
        assert!(!exc::pending());

        exc::init();
        let raising =
            contextmanager_manager(generator_function(cm_swallow_then_raise, 0, "raising"), &[]);
        assert_eq!(as_int(method(raising, "__enter__", &[])), 1);
        let boom = exception(VALUE_ERROR, "boom");
        // A different exception from the generator propagates unchanged.
        assert_eq!(method(raising, "__exit__", &[NONE, boom, NONE]), NONE);
        assert_eq!(exc::pending_tag(), VALUE_ERROR as i64);
        assert_eq!(message(), "from generator");
    }

    #[test]
    fn contextlib_contextmanager_reports_a_generator_that_keeps_going_after_throw() {
        exc::init();
        let manager = contextmanager_manager(
            generator_function(cm_swallow_then_yield, 0, "stubborn"),
            &[],
        );
        assert_eq!(as_int(method(manager, "__enter__", &[])), 1);
        let boom = exception(VALUE_ERROR, "boom");
        assert_eq!(method(manager, "__exit__", &[NONE, boom, NONE]), NONE);
        assert_eq!(exc::pending_tag(), crate::exc::RUNTIME_ERROR as i64);
        assert_eq!(message(), "generator didn't stop after throw()");
    }

    #[test]
    fn contextlib_contextmanager_forwards_positional_and_keyword_arguments() {
        exc::init();
        let manager = contextmanager_manager(generator_function(cm_echo, 1, "echo"), &[int(5)]);
        assert_eq!(as_int(method(manager, "__enter__", &[])), 5);
        assert_eq!(method(manager, "__exit__", &[NONE, NONE, NONE]), FALSE);

        exc::init();
        let function = generator_function(cm_echo, 1, "echo");
        value::function_set_params(function, vec!["value".to_string()]);
        let decorator = call("contextlib", "contextmanager", &[function]);
        assert!(!exc::pending());
        let words = [string("value"), int(9)];
        let manager =
            crate::core::builtins::call_kw(decorator, 0, std::ptr::null(), 1, words.as_ptr());
        assert!(!exc::pending());
        assert_eq!(as_int(method(manager, "__enter__", &[])), 9);
        assert_eq!(method(manager, "__exit__", &[NONE, NONE, NONE]), FALSE);
    }

    #[test]
    fn contextlib_contextmanager_rejects_a_non_generator_result() {
        exc::init();
        let entry: extern "C" fn(*const i64) -> i64 = cm_not_a_generator;
        let plain = value::function_new(entry as usize, 0, "plain".to_string());
        let manager = contextmanager_manager(plain, &[]);
        assert_eq!(method(manager, "__enter__", &[]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        assert_eq!(message(), "'int' object is not a generator");
    }

    // Fixtures for the `closing`/`ExitStack` tests. The native methods stand
    // in for Python methods: the bound call prepends the receiver, so
    // `__exit__` receives `[self, exc_type, exc, tb]`.

    extern "C" fn closing_fixture_close(argv: *const i64) -> i64 {
        let resource = unsafe { *argv };
        let roots = crate::heap::root_values(&[resource]);
        value::instance_setattr(resource, "closed".to_string(), TRUE);
        crate::heap::release_roots(roots);
        NONE
    }

    /// A resource whose `close` method records the call on the instance.
    fn closing_fixture() -> i64 {
        let close = value::function_new(
            closing_fixture_close as *const () as usize,
            1,
            "close".to_string(),
        );
        let roots = crate::heap::root_values(&[close]);
        let class = value::class_new(
            "ClosingFixture".to_string(),
            NONE,
            vec![("close".to_string(), close)],
        );
        let class_roots = crate::heap::root_values(std::slice::from_ref(&class));
        let instance = value::instance_new(class);
        crate::heap::release_roots(class_roots);
        crate::heap::release_roots(roots);
        instance
    }

    extern "C" fn stack_manager_enter(argv: *const i64) -> i64 {
        let manager = unsafe { *argv };
        value::instance_attr(manager, "tag").unwrap_or(NONE)
    }

    extern "C" fn stack_manager_exit(argv: *const i64) -> i64 {
        let manager = unsafe { *argv };
        let roots = crate::heap::root_values(&[manager]);
        let log = value::instance_attr(manager, "log").unwrap_or(NONE);
        let tag = value::instance_attr(manager, "tag").unwrap_or(NONE);
        // `argv[1]` is the exception type and `argv[2]` the exception.
        let exception = unsafe { *argv.add(2) };
        let seen_roots = crate::heap::root_values(&[log, tag, exception]);
        let _ = crate::container::list_append(log, tag);
        value::instance_setattr(manager, "seen".to_string(), exception);
        let suppresses = value::instance_attr(manager, "suppress").is_some_and(value::truthy);
        crate::heap::release_roots(seen_roots);
        crate::heap::release_roots(roots);
        if suppresses {
            TRUE
        } else {
            FALSE
        }
    }

    /// A context manager that appends `tag` to `log` on exit and reports
    /// whether it suppresses the block exception.
    fn stack_manager(log: i64, tag: i64, suppress: bool) -> i64 {
        let enter = value::function_new(
            stack_manager_enter as *const () as usize,
            1,
            "__enter__".to_string(),
        );
        let exit = value::function_new(
            stack_manager_exit as *const () as usize,
            4,
            "__exit__".to_string(),
        );
        let roots = crate::heap::root_values(&[enter, exit]);
        let class = value::class_new(
            "StackManager".to_string(),
            NONE,
            vec![
                ("__enter__".to_string(), enter),
                ("__exit__".to_string(), exit),
            ],
        );
        let class_roots = crate::heap::root_values(std::slice::from_ref(&class));
        let instance = value::instance_new(class);
        let instance_roots = crate::heap::root_values(&[instance]);
        value::instance_setattr(instance, "log".to_string(), log);
        value::instance_setattr(instance, "tag".to_string(), tag);
        value::instance_setattr(
            instance,
            "suppress".to_string(),
            if suppress { TRUE } else { FALSE },
        );
        crate::heap::release_roots(instance_roots);
        crate::heap::release_roots(class_roots);
        crate::heap::release_roots(roots);
        instance
    }

    extern "C" fn stack_record(argv: *const i64) -> i64 {
        let log = unsafe { *argv };
        let tag = unsafe { *argv.add(1) };
        let roots = crate::heap::root_values(&[log, tag]);
        let _ = crate::container::list_append(log, tag);
        crate::heap::release_roots(roots);
        NONE
    }

    extern "C" fn stack_exit_suppressor(_argv: *const i64) -> i64 {
        TRUE
    }

    fn recorded(log: i64) -> Vec<i64> {
        value::as_list(log)
            .unwrap_or_default()
            .iter()
            .map(|item| value::as_integer(*item).unwrap_or(i64::MIN))
            .collect()
    }

    fn stack_callback_count(stack: i64) -> usize {
        value::as_list(attribute(stack, "_exit_callbacks")).map_or(0, |items| items.len())
    }

    #[test]
    fn contextlib_closing_closes_on_both_paths_and_never_suppresses() {
        exc::init();
        let resource = closing_fixture();
        let closer = call("contextlib", "closing", &[resource]);
        assert!(!exc::pending());
        assert_eq!(
            value::class_display_name(value::instance_class_value(closer).expect("instance")),
            Some("closing")
        );
        assert_eq!(method(closer, "__enter__", &[]), resource);
        assert_eq!(method(closer, "__exit__", &[NONE, NONE, NONE]), FALSE);
        assert!(!exc::pending());
        assert_eq!(attribute(resource, "closed"), TRUE);

        // The exception path closes too and still reports no suppression.
        exc::init();
        let resource = closing_fixture();
        let closer = call("contextlib", "closing", &[resource]);
        let boom = exception(VALUE_ERROR, "boom");
        assert_eq!(method(closer, "__exit__", &[NONE, boom, NONE]), FALSE);
        assert!(!exc::pending());
        assert_eq!(attribute(resource, "closed"), TRUE);
    }

    #[test]
    fn contextlib_exitstack_unwinds_callbacks_in_lifo_order() {
        exc::init();
        let log = value::list_new(Vec::new());
        let stack = call("contextlib", "ExitStack", &[]);
        assert!(!exc::pending());
        assert_eq!(
            value::class_display_name(value::instance_class_value(stack).expect("instance")),
            Some("ExitStack")
        );
        assert_eq!(method(stack, "__enter__", &[]), stack);
        assert_eq!(stack_callback_count(stack), 0);

        let first = stack_manager(log, int(1), false);
        let second = stack_manager(log, int(2), false);
        assert_eq!(method(stack, "enter_context", &[first]), int(1));
        assert_eq!(method(stack, "enter_context", &[second]), int(2));
        let record =
            value::function_new(stack_record as *const () as usize, 2, "record".to_string());
        assert_eq!(method(stack, "callback", &[record, log, int(3)]), record);
        assert_eq!(stack_callback_count(stack), 3);

        assert_eq!(method(stack, "close", &[]), NONE);
        assert!(!exc::pending());
        // Last registered runs first; the callback precedes both managers.
        assert_eq!(recorded(log), vec![3, 2, 1]);
        assert_eq!(stack_callback_count(stack), 0);
        // Closing an empty stack is a no-op.
        assert_eq!(method(stack, "close", &[]), NONE);
        assert!(!exc::pending());
        assert_eq!(recorded(log), vec![3, 2, 1]);

        // An object without the context-manager protocol is rejected before
        // anything is registered.
        exc::init();
        assert_eq!(method(stack, "enter_context", &[int(1)]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        assert_eq!(
            message(),
            "'int' object does not support the context manager protocol"
        );
        assert_eq!(stack_callback_count(stack), 0);
    }

    #[test]
    fn contextlib_exitstack_exit_passes_and_suppresses_exceptions() {
        exc::init();
        let log = value::list_new(Vec::new());
        let stack = call("contextlib", "ExitStack", &[]);
        // Registered first, so it is exited last and sees the suppressed
        // exception as `None` once the later manager swallows it.
        let outer = stack_manager(log, int(1), false);
        let inner = stack_manager(log, int(2), true);
        method(stack, "enter_context", &[outer]);
        method(stack, "enter_context", &[inner]);
        let boom = exception(VALUE_ERROR, "boom");
        assert_eq!(method(stack, "__exit__", &[NONE, boom, NONE]), TRUE);
        assert!(!exc::pending());
        assert_eq!(attribute(inner, "seen"), boom);
        assert_eq!(attribute(outer, "seen"), NONE);
        assert_eq!(recorded(log), vec![2, 1]);
        assert_eq!(stack_callback_count(stack), 0);

        // Without a suppressing manager the exception propagates from the
        // `with` lowering, which sees a falsy `__exit__` result.
        exc::init();
        let log = value::list_new(Vec::new());
        let stack = call("contextlib", "ExitStack", &[]);
        let first = stack_manager(log, int(1), false);
        let second = stack_manager(log, int(2), false);
        method(stack, "enter_context", &[first]);
        method(stack, "enter_context", &[second]);
        let boom = exception(VALUE_ERROR, "boom");
        assert_eq!(method(stack, "__exit__", &[NONE, boom, NONE]), FALSE);
        assert!(!exc::pending());
        assert_eq!(attribute(first, "seen"), boom);
        assert_eq!(attribute(second, "seen"), boom);

        // The normal path passes `None` and never reports suppression.
        exc::init();
        let stack = call("contextlib", "ExitStack", &[]);
        let manager = stack_manager(value::list_new(Vec::new()), int(7), true);
        method(stack, "enter_context", &[manager]);
        assert_eq!(method(stack, "__exit__", &[NONE, NONE, NONE]), FALSE);
        assert_eq!(attribute(manager, "seen"), NONE);
        assert!(!exc::pending());
    }

    #[test]
    fn contextlib_exitstack_push_accepts_plain_exit_callables() {
        exc::init();
        let log = value::list_new(Vec::new());
        let stack = call("contextlib", "ExitStack", &[]);
        let manager = stack_manager(log, int(1), false);
        // `push` resolves `__exit__` on a manager...
        assert_eq!(method(stack, "push", &[manager]), manager);
        // ...but registers a callable without one directly, keeping its
        // truthiness as the suppression decision.
        let suppressor = value::function_new(
            stack_exit_suppressor as *const () as usize,
            3,
            "exit_true".to_string(),
        );
        assert_eq!(method(stack, "push", &[suppressor]), suppressor);
        assert_eq!(stack_callback_count(stack), 2);
        let boom = exception(VALUE_ERROR, "boom");
        assert_eq!(method(stack, "__exit__", &[NONE, boom, NONE]), TRUE);
        assert!(!exc::pending());
        assert_eq!(recorded(log), vec![1]);
        assert_eq!(attribute(manager, "seen"), NONE);

        // `callback` cannot suppress even when it returns a truthy value.
        exc::init();
        let stack = call("contextlib", "ExitStack", &[]);
        let truthy = value::function_new(
            stack_exit_suppressor as *const () as usize,
            0,
            "truthy".to_string(),
        );
        method(stack, "callback", &[truthy]);
        let boom = exception(VALUE_ERROR, "boom");
        assert_eq!(method(stack, "__exit__", &[NONE, boom, NONE]), FALSE);
        assert!(!exc::pending());
    }

    #[test]
    fn contextlib_exitstack_callback_forwards_arguments_and_keywords() {
        exc::init();
        let log = value::list_new(Vec::new());
        let record =
            value::function_new(stack_record as *const () as usize, 2, "record".to_string());
        let numbers = value::list_new(vec![int(2), int(3), int(4)]);
        let prod = get("math", "prod");

        // The stored entry keeps the callable, its bound positional arguments
        // and its keyword arguments.
        let stack = call("contextlib", "ExitStack", &[]);
        assert_eq!(method(stack, "callback", &[record, log, int(5)]), record);
        let callbacks = attribute(stack, "_exit_callbacks");
        let entry = value::as_list(callbacks).expect("callbacks list")[0];
        let parts = value::as_tuple(entry).expect("entry tuple");
        assert_eq!((parts[0], parts[3]), (record, FALSE));
        assert_eq!(
            value::as_tuple(parts[1]).expect("bound args"),
            &[log, int(5)][..]
        );
        assert_eq!(value::as_dict(parts[2]).expect("bound keywords").len(), 0);

        // A callback runs with its arguments even though it cannot suppress.
        assert_eq!(method(stack, "close", &[]), NONE);
        assert!(!exc::pending());
        assert_eq!(recorded(log), vec![5]);

        // Keywords travel to the callee: `math.prod(..., start=10)` accepts
        // `start`, and an unknown name is reported by `prod` itself.
        exc::init();
        let stack = call("contextlib", "ExitStack", &[]);
        assert_eq!(
            method_kw(stack, "callback", &[prod, numbers], &[("start", int(10))]),
            prod
        );
        assert!(!exc::pending());
        assert_eq!(method(stack, "close", &[]), NONE);
        assert!(!exc::pending());

        exc::init();
        let stack = call("contextlib", "ExitStack", &[]);
        method_kw(stack, "callback", &[prod, numbers], &[("bogus", int(1))]);
        assert!(!exc::pending());
        assert_eq!(method(stack, "close", &[]), NONE);
        assert_eq!(exc::pending_tag(), TYPE_ERROR as i64);
        assert_eq!(
            message(),
            "prod() got an unexpected keyword argument 'bogus'"
        );
    }

    #[test]
    fn contextlib_exitstack_pop_all_transfers_the_pending_callbacks() {
        exc::init();
        let log = value::list_new(Vec::new());
        let record =
            value::function_new(stack_record as *const () as usize, 2, "record".to_string());
        let stack = call("contextlib", "ExitStack", &[]);
        method(stack, "callback", &[record, log, int(1)]);
        method(stack, "callback", &[record, log, int(2)]);

        let transferred = method(stack, "pop_all", &[]);
        assert!(!exc::pending());
        assert_ne!(transferred, stack);
        assert_eq!(
            value::class_display_name(
                value::instance_class_value(transferred).expect("transferred instance")
            ),
            Some("ExitStack")
        );
        assert_eq!(stack_callback_count(stack), 0);
        assert_eq!(stack_callback_count(transferred), 2);

        // The old stack keeps working, independently of the transferred ones.
        method(stack, "callback", &[record, log, int(3)]);
        assert_eq!(method(stack, "close", &[]), NONE);
        assert_eq!(recorded(log), vec![3]);
        // The transferred callbacks keep their original LIFO order.
        assert_eq!(method(transferred, "close", &[]), NONE);
        assert!(!exc::pending());
        assert_eq!(recorded(log), vec![3, 2, 1]);

        // CPython always returns a fresh stack, even when nothing is pending.
        exc::init();
        let empty = call("contextlib", "ExitStack", &[]);
        let moved = method(empty, "pop_all", &[]);
        assert!(!exc::pending());
        assert_ne!(moved, empty);
        assert_eq!(stack_callback_count(moved), 0);
        assert_eq!(stack_callback_count(empty), 0);
    }

    #[test]
    fn contextlib_abstract_manager_classes_expose_the_protocol() {
        exc::init();
        let manager = get("contextlib", "AbstractContextManager");
        assert_eq!(
            value::class_display_name(manager),
            Some("AbstractContextManager")
        );
        // CPython's concrete bodies: `__enter__` returns the manager and
        // `__exit__` returns None, so block exceptions propagate.
        let instance = value::instance_new(manager);
        assert_eq!(method(instance, "__enter__", &[]), instance);
        assert_eq!(method(instance, "__exit__", &[NONE, NONE, NONE]), NONE);
        assert!(!exc::pending());

        // The structural hook accepts a class defining both protocol methods
        // and reports NotImplemented for one that does not.
        let enter = value::native_function_new("fixture", "enter", 1);
        let exit = value::native_function_new("fixture", "exit", 4);
        let complete = value::class_new(
            "Complete".to_string(),
            NONE,
            vec![
                ("__enter__".to_string(), enter),
                ("__exit__".to_string(), exit),
            ],
        );
        assert_eq!(
            method(manager, "__subclasshook__", &[complete]),
            value::TRUE
        );
        let partial = value::class_new("Partial".to_string(), NONE, Vec::new());
        assert_eq!(
            method(manager, "__subclasshook__", &[partial]),
            value::NOT_IMPLEMENTED
        );

        // The async spelling carries the awaitable protocol names and is
        // imported by `typing_extensions` as the `AsyncContextManager` origin.
        let asynchronous = get("contextlib", "AbstractAsyncContextManager");
        assert_eq!(
            value::class_display_name(asynchronous),
            Some("AbstractAsyncContextManager")
        );
        let asynchronous_instance = value::instance_new(asynchronous);
        assert_eq!(
            method(asynchronous_instance, "__aenter__", &[]),
            asynchronous_instance
        );
        assert_eq!(
            method(asynchronous_instance, "__aexit__", &[NONE, NONE, NONE]),
            NONE
        );
        assert!(!exc::pending());
    }

    #[test]
    fn os_fspath_passes_through_and_asks_path_like_objects() {
        exc::init();
        let text_path = string("data.txt");
        assert_eq!(call("os", "fspath", &[text_path]), text_path);
        let raw = value::bytes_new(b"data.bin".to_vec());
        assert_eq!(call("os", "fspath", &[raw]), raw);

        let path = call("pathlib", "Path", &[string("/tmp/data.txt")]);
        assert_eq!(
            value::as_str(call("os", "fspath", &[path])),
            Some("/tmp/data.txt")
        );

        // A class implementing `__fspath__` is asked for its result; the
        // native function stands in for the user method and returns a str.
        let methods = vec![(
            "__fspath__".to_string(),
            value::native_function_new("builtins", "repr", 1),
        )];
        let class = value::class_new("PathLikeFixture".to_string(), NONE, methods);
        let fixture = value::instance_new(class);
        let resolved = call("os", "fspath", &[fixture]);
        assert!(!exc::pending());
        assert!(value::as_str(resolved).is_some_and(|text| !text.is_empty()));
    }

